import {
  rankDiscourseNodesByTitle,
  type RankedDiscourseNode,
  type SearchableNode,
} from "~/services/QueryEngine";
import type { DiscourseNode } from "~/types";

// Matches Roam's summoning menu.
const MAX_NODES_PER_TYPE = 10;

export type SummonMenuGroup = {
  nodeType: DiscourseNode;
  nodes: RankedDiscourseNode[];
};

export const groupNodesForSummonMenu = ({
  nodes,
  nodeTypes,
  query,
}: {
  nodes: SearchableNode[];
  nodeTypes: DiscourseNode[];
  query: string;
}): SummonMenuGroup[] => {
  const ranked = rankDiscourseNodesByTitle({ candidates: nodes, query });

  return nodeTypes
    .map((nodeType) => ({
      nodeType,
      nodes: ranked
        .filter((node) => node.nodeTypeId === nodeType.id)
        .slice(0, MAX_NODES_PER_TYPE),
    }))
    .filter((group) => group.nodes.length > 0);
};
import { describe, expect, it } from "vitest";
import { validateNodeSearchTrigger } from "~/utils/nodeSearchTrigger";

describe("validateNodeSearchTrigger", () => {
  it("rejects a trigger the node tag hotkey would swallow", () => {
    expect(
      validateNodeSearchTrigger({ value: "\\", nodeTagHotkey: "\\" }),
    ).not.toBeNull();
    expect(
      validateNodeSearchTrigger({ value: "@\\", nodeTagHotkey: "\\" }),
    ).not.toBeNull();
  });

  it("rejects a trigger longer than 5 characters", () => {
    expect(
      validateNodeSearchTrigger({ value: "@@@@@@", nodeTagHotkey: "\\" }),
    ).not.toBeNull();
  });

  it("accepts the default, an empty trigger, and any trigger when no hotkey is set", () => {
    expect(
      validateNodeSearchTrigger({ value: "@", nodeTagHotkey: "\\" }),
    ).toBeNull();
    expect(
      validateNodeSearchTrigger({ value: "", nodeTagHotkey: "\\" }),
    ).toBeNull();
    expect(
      validateNodeSearchTrigger({ value: "@@", nodeTagHotkey: "" }),
    ).toBeNull();
  });
});
